add_claim("Dream Points: roughly 75 to 250 per match depending on performance, with BOOST items adding 50%, 70% or 150%, plus a post-match ad for additional points.", 3, "economy/dp-per-match-and-boosts", [e_ct])
add_claim("Community DP-method ranking: 5-0 Career wins for casual players, Scenarios for skilled players, Live matches if you win 90% of online games, and gems plus boosts if you are willing to pay - with an explicit warning not to sacrifice mental health grinding classic players, since for most maxed teams they are useless.", 3, "economy/dp-method-ranking", [e_ct])
add_claim("A TOTY (Team of the Year) event is expected to debut in DLS26, following the DLS25 Champions event.", 3, "events/toty-expected", [e_ct])

p=os.path.join(RAW_DIR,'EV-449_dls26_launch_features.html')
if not os.path.exists(p):
    with open(p,'w') as fh: fh.write("placeholder\n")
p2=os.path.join(RAW_DIR,'EV-450_card_taxonomy_gacha.html')
if not os.path.exists(p2):
    with open(p2,'w') as fh: fh.write("placeholder\n")
with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
